    code: "import numpy as np\n\nz = np.array([-2.0, 0.0, 3.0])\n\nsigmoid = 1 / (1 + np.exp(-z))\nrelu = np.maximum(0, z)\nsoftmax = np.exp(z) / np.exp(z).sum()\n\nprint(\"input  :\", z)\nprint(\"sigmoid:\", sigmoid.round(3))\nprint(\"relu   :\", relu)\nprint(\"softmax:\", softmax.round(3), \"sum =\", round(softmax.sum(), 3))",
